/// <summary>
/// يجمع الـactivities عبر ActivityListener — مستقل تمامًا عن إعداد التطبيق،
/// فلا يتعارض مع الـexporter الإنتاجي (7.1.2).
/// ملاحظة: Sample لازم يرجع AllDataAndRecorded وإلا السمات ما تتسجلش.
/// </summary>
public sealed class ActivityCollectorFixture : IDisposable
{
    private readonly ActivityListener _listener;

    public ConcurrentQueue<Activity> Activities { get; } = new();

    public ActivityCollectorFixture()
    {
        _listener = new ActivityListener
        {
            ShouldListenTo = src =>
                src.Name.StartsWith("Shop.", StringComparison.Ordinal)
                || src.Name.StartsWith("Microsoft.AspNetCore.Hosting", StringComparison.Ordinal)
                || src.Name.StartsWith("System.Net.Http", StringComparison.Ordinal),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => Activities.Enqueue(activity),
        };
        ActivitySource.AddActivityListener(_listener);
    }

    public void Reset()
    {
        while (Activities.TryDequeue(out _)) { }
    }

    /// <summary>ينتظر العدد المطلوب (أو نهاية المهلة) ويرجع ما تجمع.</summary>
    public IReadOnlyList<Activity> WaitFor(int count, int timeoutMs = 10_000)
    {
        var deadline = Environment.TickCount64 + timeoutMs;
        while (Environment.TickCount64 < deadline && Activities.Count < count)
        {
            Thread.Sleep(50);
        }

        return Activities.ToArray();
    }

    public void Dispose() => _listener.Dispose();
}

/// <summary>
/// ثوابت المشروع: لو اختبار فشل هنا فالمراقبة/الأمان/الخصوصية انكسرت بصمت.
/// الأسماء تحمل معرفات التهديدات (T-xxx) من docs/threat-model/threats.md.
/// </summary>
public sealed class ObservabilityInvariants(
    WebApplicationFactory<Program> factory,
    ActivityCollectorFixture collector)
    : IClassFixture<WebApplicationFactory<Program>>, IClassFixture<ActivityCollectorFixture>
{
    // ── المراقبة ────────────────────────────────────────────────────────
    [Fact]
    public async Task Traced_Request_Produces_Shop_Span_Without_Identifiers_In_Tags()
    {
        collector.Reset();
        using var client = factory.CreateClient();

        await client.GetAsync("/health");                      // مستثنى من التتبع
        await client.GetAsync("/catalog/items?cursor=0");      // يجب أن يُتتبع

        var spans = collector.WaitFor(2);
        var catalog = spans.FirstOrDefault(a =>
            a.OperationName.Contains("catalog", StringComparison.OrdinalIgnoreCase));

        catalog.ShouldNotBeNull("لا يوجد span لمسار الكتالوج — التتبع غير مفعّل على هذا المسار");
        // service.name سمة مورد (resource) في OTLP، مش سمة على الـactivity — تُفحص في الـCollector
        catalog!.GetTagItem("http.response.status_code").ShouldBe(200);
        // لا معرّفات في السمات: انفجار cardinality (7.1.1)
        catalog.TagObjects.ShouldNotContain(t => t.Key is "user_id" or "customer_id" or "order_id");
    }

    [Fact]
    public async Task Health_Endpoint_Is_Not_Traced()
    {
        collector.Reset();
        using var client = factory.CreateClient();
        await client.GetAsync("/health");
        await client.GetAsync("/alive");

        collector.WaitFor(1).ShouldNotContain(a =>
            a.OperationName.Contains("/health", StringComparison.OrdinalIgnoreCase)
            || a.OperationName.Contains("/alive", StringComparison.OrdinalIgnoreCase));
    }

    [Fact]
    public async Task Queue_Consumer_Joins_The_Same_Trace_As_Producer()
    {
        collector.Reset();
        using var client = factory.CreateClient();

        var placed = await client.PostAsJsonAsync("/orders", new { sku = "SKU-1", qty = 1 });
        placed.StatusCode.ShouldBeOneOf(HttpStatusCode.Accepted, HttpStatusCode.Created);

        var spans = collector.WaitFor(6, timeoutMs: 15_000);
        var producer = spans.FirstOrDefault(a => a.Kind == ActivityKind.Producer);
        var consumer = spans.FirstOrDefault(a => a.Kind == ActivityKind.Consumer);

        producer.ShouldNotBeNull("لا span من نوع Producer — النشر عبر الطابور بلا تحقق (7.1.2)");
        consumer.ShouldNotBeNull("لا span من نوع Consumer — العامل لا يستخرج السياق");
        consumer!.TraceId.ShouldBe(producer!.TraceId);
    }

    [Fact]
    public async Task Response_Contains_CorrelationId_Header()
    {
        using var client = factory.CreateClient();
        var res = await client.GetAsync("/catalog/items?cursor=0");

        res.Headers.TryGetValues("X-Correlation-Id", out var values).ShouldBeTrue();
        values!.First().ShouldNotBeNullOrWhiteSpace();
    }

    // ── الأمان (7.2.3) ──────────────────────────────────────────────────
    [Fact]
    public async Task Security_Headers_Are_Present_With_Nonce_Based_Csp()
    {
        using var client = factory.CreateClient();
        var res = await client.GetAsync("/catalog/items?cursor=0");

        res.Headers.TryGetValues("X-Content-Type-Options", out var nosniff).ShouldBeTrue();
        nosniff!.ShouldContain("nosniff");

        res.Headers.TryGetValues("Content-Security-Policy", out var cspValues).ShouldBeTrue();
        var csp = string.Join(" ", cspValues!);
        csp.ShouldNotContain("unsafe-inline");      // unsafe-inline يلغي معظم قيمة CSP
        csp.ShouldContain("nonce-");
        csp.ShouldContain("frame-ancestors 'none'");

        res.Headers.TryGetValues("Referrer-Policy", out _).ShouldBeTrue();
    }

    [Fact]
    public async Task Error_Response_Is_ProblemDetails_Without_Internal_Details()
    {
        using var client = factory.CreateClient();
        var res = await client.GetAsync("/definitely-not-a-route");

        res.StatusCode.ShouldBe(HttpStatusCode.NotFound);
        res.Content.Headers.ContentType?.MediaType.ShouldBe("application/problem+json");

        var body = await res.Content.ReadAsStringAsync();
        body.ShouldNotContain("at Shop.");
        body.ShouldNotContain("Stack trace");
        body.ShouldNotContain("Password=");
    }

    [Fact]
    public async Task T001_User_Cannot_Read_Another_Users_Order()
    {
        // تهديد T-001 (إفصاح / IDOR) — الإجراء المضاد: فحص ملكية المورد
        using var alice = factory.CreateAuthenticatedClient("alice");
        using var bob = factory.CreateAuthenticatedClient("bob");

        var created = await alice.PostAsJsonAsync("/orders", new { sku = "SKU-1", qty = 1 });
        created.StatusCode.ShouldBeOneOf(HttpStatusCode.Created, HttpStatusCode.Accepted);
        var location = created.Headers.Location?.ToString() ?? "/orders/mine/last";

        var stolen = await bob.GetAsync(location);
        stolen.StatusCode.ShouldBeOneOf(HttpStatusCode.Forbidden, HttpStatusCode.NotFound);
    }

    [Fact]
    public async Task Sensitive_Operations_Are_Audited_With_Actor_From_Token()
    {
        using var client = factory.CreateAuthenticatedClient("alice");
        await client.PostAsJsonAsync("/orders", new { sku = "SKU-1", qty = 1 });

        // نقرأ جدول التدقيق مباشرة (7.2.3) — append-only وبلا endpoint تعديل
        using var scope = factory.Services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ShopDbContext>();

        var row = await db.AuditEntries
            .AsNoTracking()
            .Where(a => a.Action == "Created" && a.EntityType == "Order")
            .OrderByDescending(a => a.Id)
            .FirstOrDefaultAsync();

        row.ShouldNotBeNull("لا صف تدقيق للعملية — الـinterceptor غير مسجّل");
        row!.ActorId.ShouldBe("alice");     // من التوكن، لا من مدخلات الطلب
        row.ActorType.ShouldBe("user");
        row.CorrelationId.ShouldNotBeNullOrWhiteSpace();
    }

    // ── الخصوصية (7.2.5) ────────────────────────────────────────────────
    [Fact]
    public void PiiRedactionEnricher_Hides_Phone_Card_And_Email_In_Message_And_Properties()
    {
        var events = new List<LogEvent>();
        using var log = new LoggerConfiguration()
            .MinimumLevel.Debug()
            .Enrich.With(new PiiRedactionEnricher())      // من 7.1.3
            .WriteTo.Sink(new CollectingSink(events))
            .CreateLogger();

        log.Information("customer {Phone} paid with {Card} ({Email})",
            "01012345678", "4242424242424242", "mona@example.com");

        events.ShouldNotBeEmpty();
        var rendered = string.Join("\n", events.Select(Render));
        rendered.ShouldNotContain("01012345678");
        rendered.ShouldNotContain("4242424242424242");
        rendered.ShouldNotContain("mona@example.com");
        // الإخفاء لازم يشمل السمات المهيكلة، لا نص الرسالة فقط
        rendered.ShouldContain("pii.detected");
    }

    private static string Render(LogEvent e)
    {
        var message = e.RenderMessage(CultureInfo.InvariantCulture);
        var props = string.Join(" ", e.Properties.Select(kv => $"{kv.Key}={kv.Value}"));
        return message + " " + props;
    }

    [Fact]
    public async Task Erasure_Covers_All_Stores_And_Invalidates_The_Subject_Key()
    {
        using var client = factory.CreateAuthenticatedClient("alice");
        var subject = await client.GetFromJsonAsync<MeDto>("/customers/me");
        subject.ShouldNotBeNull();

        // نفترض تصميم مفتاح لكل مستخدم (شرط crypto-shredding — 7.2.5)
        var enc = factory.Services.GetRequiredService<IFieldEncryptor>();
        var cipher = enc.EncryptFor(subject!.Id, "01012345678", KeyPurpose.CustomerContact);
        enc.DecryptFor(subject.Id, cipher, KeyPurpose.CustomerContact).ShouldBe("01012345678");

        var requested = await client.PostAsJsonAsync("/me/erasure", new { reason = "test" });
        requested.StatusCode.ShouldBe(HttpStatusCode.Accepted);
        var ack = await requested.Content.ReadFromJsonAsync<ErasureAck>();

        // الطلب المكرر لازم يرجع نفس المرجع (idempotency)
        var again = await client.PostAsJsonAsync("/me/erasure", new { reason = "test" });
        var ack2 = await again.Content.ReadFromJsonAsync<ErasureAck>();
        ack2!.Reference.ShouldBe(ack!.Reference);

        var status = await client.PollUntilAsync<ErasureStatusDto>(
            $"/me/erasure/{ack.Reference}", s => s.State is "completed" or "partially_failed",
            TimeSpan.FromSeconds(30));

        status.State.ShouldBe("completed");
        status.Stores.Count.ShouldBeGreaterThanOrEqualTo(6);
        status.Stores.ShouldAllBe(x => x.Outcome == "done");

        // crypto-shredding: بعد إبطال المفتاح، فك التشفير يفشل — والنسخ الاحتياطية بقت بلا قيمة
        Should.Throw<CryptographicException>(
            () => enc.DecryptFor(subject.Id, cipher, KeyPurpose.CustomerContact));
    }

    [Fact]
    public async Task Export_Returns_Only_The_Current_Users_Data()
    {
        using var alice = factory.CreateAuthenticatedClient("alice");
        using var bob = factory.CreateAuthenticatedClient("bob");
        await bob.PostAsJsonAsync("/customers/me", new { fullName = "Bob", email = "bob@example.com" });

        var json = await alice.GetStringAsync("/me/export");
        json.ShouldContain("alice", Case.Insensitive);
        json.ShouldNotContain("bob@example.com");   // لا تسرب بين المستخدمين
    }
}

// ── أدوات مساعدة للاختبار ───────────────────────────────────────────────
internal sealed class CollectingSink(List<LogEvent> sink) : ILogEventSink
{
    public void Emit(LogEvent logEvent) => sink.Add(logEvent);
}

public sealed record MeDto(Guid Id, string FullName, string Email);
public sealed record ErasureAck(string Reference);
public sealed record ErasureStatusDto(string Reference, string State, List<StoreResultDto> Stores);
public sealed record StoreResultDto(string Store, string Action, string Outcome);

public static class TestHttpExtensions
{
    public static HttpClient CreateAuthenticatedClient(
        this WebApplicationFactory<Program> factory, string subject)
    {
        var client = factory.CreateClient();
        client.DefaultRequestHeaders.Authorization =
            new AuthenticationHeaderValue("Bearer", TestTokens.For(subject));
        return client;
    }

    public static async Task<T> PollUntilAsync<T>(
        this HttpClient client, string url, Func<T, bool> predicate, TimeSpan timeout)
        where T : class
    {
        var deadline = DateTime.UtcNow + timeout;
        while (DateTime.UtcNow < deadline)
        {
            var value = await client.GetFromJsonAsync<T>(url);
            if (value is not null && predicate(value))
            {
                return value;
            }

            await Task.Delay(250);
        }

        throw new TimeoutException("لم يتحقق الشرط على " + url + " خلال " + timeout);
    }
}

/// <summary>
/// توكنات اختبار موقعة بمفتاح اختبار — لازم إعدادات الاختبار في التطبيق تتحقق
/// من نفس المفتاح (2.2.7). لا تستخدم هذا المفتاح في أي بيئة حقيقية.
/// </summary>
internal static class TestTokens
{
    private static readonly SymmetricSecurityKey Key = new(
        Encoding.UTF8.GetBytes(
            Environment.GetEnvironmentVariable("TEST_JWT_SIGNING_KEY")
            ?? throw new InvalidOperationException("عيّن TEST_JWT_SIGNING_KEY (32 حرفًا على الأقل)")));

    public static string For(string subject) => new JsonWebTokenHandler().CreateToken(
        new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(
            [
                new Claim("sub", subject),
                new Claim(ClaimTypes.Name, subject),
                new Claim("role", "customer"),
            ]),
            Expires = DateTime.UtcNow.AddMinutes(10),
            Issuer = "shop-tests",
            Audience = "shop-api",
            SigningCredentials = new SigningCredentials(Key, SecurityAlgorithms.HmacSha256),
        });
}
